.heading-fancy {
  font-family: "Playfair Display", serif; /* Requires a font with OpenType features */
  font-feature-settings: "dlig" 1, "ss01" 1; /* Enable discretionary ligatures & stylistic set 1 */
  letter-spacing: -0.01em; /* Fine-tune spacing for aesthetic impact */
}

.data-table-numbers {
  font-family: "Inter", sans-serif; /* A font known for good numeral features */
  font-feature-settings: "tnum" 1, "lnum" 1; /* Ensure tabular lining numbers for alignment */
  /* Values can be '1' or 'on' */
}
